}

export interface Projectile {
  id: EntityId;
  x: number;
  y: number;
  targetId: EntityId;
  damage: number;
  speed: number;
  faction: Faction;
}

export interface ResourceCounts {
  gold: number;
  wood: number;
  supplyUsed: number;
  supplyCap: number;
}

export interface StartLocation {
  col: number;
  row: number;
  faction: Faction;
}

export interface LevelConfig {
  width: number;
  height: number;
  levelNumber: number;
  difficulty: number;
}

export interface GameConfig {
  seed: number;
  level: number;
  playerFaction: Faction;
  prng: PRNG;
}

/** Data-driven stats table. Every combat/economy number lives here. */

