function canMoveDiagonal(map: GameMap, fc: number, fr: number, tc: number, tr: number): boolean {
  // Corner cutting: diagonal move blocked if both adjacent cardinal tiles are unwalkable
  const sameRow = fc; // horizontal neighbor
  const sameCol = tc; // vertical neighbor — the other cardinals
  // For a diagonal from (fc,fr) to (tc,tr), the two adjacent cardinals are (fc,tr) and (tc,fr)
  return isWalkable(map.getTile(fc, tr)) && isWalkable(map.getTile(tc, fr));
}

