import tseslint from "typescript-eslint";

const PRNG_FILE = "src/sim/prng.ts";

export default tseslint.config(
  ...tseslint.configs.recommended,
  {
    files: ["src/**/*.ts", "tests/**/*.ts"],
    rules: {
      "@typescript-eslint/no-explicit-any": "error",
      "@typescript-eslint/no-non-null-assertion": "error",
      "@typescript-eslint/no-unused-vars": ["error", { "argsIgnorePattern": "^_", "varsIgnorePattern": "^_" }],
      "no-restricted-properties": [
        "error",
        {
          "object": "Math",
          "property": "random",
          "message": "Use the seeded PRNG from src/sim/prng.ts instead of Math.random."
        }
      ],
      "max-lines": ["error", { max: 500, skipBlankLines: true, skipComments: true }],
    },
  },
  {
    files: [PRNG_FILE],
    rules: {
      "no-restricted-properties": "off",
    },
  },
);

/** Determinism and WFC tests. */

import { describe, it, expect } from "vitest";
import { createPRNG } from "../src/sim/prng";
import { generateMap } from "../src/sim/wfc";
import { GameMap } from "../src/sim/map";
import { ADJACENCY } from "../src/sim/tile";
import { World } from "../src/sim/world";
import { FOG_UNEXPLORED } from "../src/sim/constants";

describe("PRNG determinism", () => {
  it("produces identical sequences for the same seed", () => {
    const a = createPRNG(12345);
    const b = createPRNG(12345);
    for (let i = 0; i < 1000; i++) {
      expect(a.next()).toBe(b.next());
    }
  });

  it("produces different sequences for different seeds", () => {
    const a = createPRNG(12345);
    const b = createPRNG(54321);
    let same = 0;
    for (let i = 0; i < 100; i++) {
      if (a.next() === b.next()) same++;
    }
    expect(same).toBeLessThan(50);
  });

  it("fork creates independent sequences", () => {
    const a = createPRNG(12345);
    const fork = a.fork();
    const aNext = a.next();
    const forkNext = fork.next();
    // Fork uses a different sub-seed derived from the parent
    expect(typeof aNext).toBe("number");
    expect(typeof forkNext).toBe("number");
  });
});

describe("WFC map generation", () => {
  it("generates maps with no adjacency violations", () => {
    for (let seed = 1; seed <= 5; seed++) {
      const { map } = generateMap(32, 32, seed);
      for (let r = 0; r < map.height; r++) {
        for (let c = 0; c < map.width; c++) {
          const tile = map.getTile(c, r);
          // Check 4-adjacency
          for (const [dc, dr] of [[1, 0], [-1, 0], [0, 1], [0, -1]] as [number, number][]) {
            const nc = c + dc;
            const nr = r + dr;
            if (map.inBounds(nc, nr)) {
              const neighbor = map.getTile(nc, nr);
              const allowed = ADJACENCY[tile];
              expect(allowed).toContain(neighbor);
            }
          }
        }
      }
    }
  });

  it("is deterministic for a fixed seed", () => {
    const a = generateMap(32, 32, 42);
    const b = generateMap(32, 32, 42);
    expect(a.starts).toEqual(b.starts);
    for (let r = 0; r < a.map.height; r++) {
      for (let c = 0; c < a.map.width; c++) {
        expect(a.map.getTile(c, r)).toBe(b.map.getTile(c, r));
      }
    }
  });

  it("generates different maps for different seeds", () => {
    const a = generateMap(32, 32, 1);
    const b = generateMap(32, 32, 999);
    let same = 0;
    for (let r = 0; r < a.map.height; r++) {
      for (let c = 0; c < a.map.width; c++) {
        if (a.map.getTile(c, r) === b.map.getTile(c, r)) same++;
      }
    }
    // At least some tiles should differ
    expect(same).toBeLessThan(a.map.width * a.map.height);
  });
});

