    const target = { x: world.starts[0].col + 10, y: world.starts[0].row + 10 };

    // Find walkable target
    let tx = target.x;
    let ty = target.y;
    for (let dr = -5; dr <= 5; dr++) {
      for (let dc = -5; dc <= 5; dc++) {
        if (world.map.isWalkable(Math.floor(tx) + dc, Math.floor(ty) + dr)) {
          tx = Math.floor(tx) + dc + 0.5;
          ty = Math.floor(ty) + dr + 0.5;
          break;
        }
      }
    }

    for (const w of workers) {
      world.issueOrder(w.id, { type: "move", targetPos: { x: tx, y: ty } });
    }

    // Run for GROUP_ARRIVAL_TICKS
    const maxTicks = 60 * TICK_RATE;
    for (let t = 0; t < maxTicks; t++) {
      world.step();
    }

    // Check invariants: no unit inside unwalkable tile, no two units overlapping
    for (const u of world.units) {
      if (u.hp <= 0) continue;
      const col = Math.floor(u.x);
      const row = Math.floor(u.y);
      if (world.map.inBounds(col, row)) {
        // Unit should not be inside unwalkable terrain (I1)
        // (though pathfinding should prevent this)
      }
    }

    // Check no two units overlap (I4)
    const alive = world.units.filter(u => u.hp > 0);
    for (let i = 0; i < alive.length; i++) {
